import{_ as l,a0 as p,w as d,s as o,ao as h,I as n,x as i,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Linux 中一次重命名多個文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中一次重命名多個文件 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中一次重命名多個文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中一次重命名多個文件 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180615 How To Rename Multiple Files At Once In Linux","title":"如何在 Linux 中一次重命名多個文件","tag":"201810","desc":""},"relativePath":"201810/20180615 How To Rename Multiple Files At Once In Linux.md","filePath":"[post].md"}'),c={name:"201810/20180615 How To Rename Multiple Files At Once In Linux.md"};function r(g,s,u,k,b,x){const t=p("Link");return d(),o("div",null,[s[15]||(s[15]=h(`<h1 id="如何在-linux-中一次重命名多個文件" tabindex="-1">如何在 Linux 中一次重命名多個文件 <a class="header-anchor" href="#如何在-linux-中一次重命名多個文件" aria-label="Permalink to “如何在 Linux 中一次重命名多個文件”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/06/Rename-Multiple-Files-720x340.png" alt=""></p><p>你可能已經知道，我們使用 <code>mv</code> 命令在類 Unix 操作系統中重命名或者移動文件和目錄。 但是，<code>mv</code> 命令不支持一次重命名多個文件。 不用擔心。 在本教程中，我們將學習使用 Linux 中的 <code>mmv</code> 命令一次重命名多個文件。 此命令用於在類 Unix 操作系統中使用標準通配符批量移動、複製、追加和重命名文件。</p><h3 id="在-linux-中一次重命名多個文件" tabindex="-1">在 Linux 中一次重命名多個文件 <a class="header-anchor" href="#在-linux-中一次重命名多個文件" aria-label="Permalink to “在 Linux 中一次重命名多個文件”">​</a></h3><p><code>mmv</code> 程序可在基於 Debian 的系統的默認倉庫中使用。 要想在 Debian、Ubuntu、Linux Mint 上安裝它，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install mmv</span></span></code></pre></div><p>我們假設你在當前目錄中有以下文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>a1.txt a2.txt a3.txt</span></span></code></pre></div><p>現在，你想要將所有以字母 “a” 開頭的文件重命名為以 “b” 開頭的。 當然，你可以在幾秒鐘內手動執行此操作。 但是想想你是否有數百個文件想要重命名？ 這是一個非常耗時的過程。 這時候 <code>mmv</code> 命令就很有幫助了。</p><p>要將所有以字母 “a” 開頭的文件重命名為以字母 “b” 開頭的，只需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mmv a\\* b\\#1</span></span></code></pre></div><p>讓我們檢查一下文件是否都已經重命名了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>b1.txt b2.txt b3.txt</span></span></code></pre></div><p>如你所見，所有以字母 “a” 開頭的文件（即 <code>a1.txt</code>、<code>a2.txt</code>、<code>a3.txt</code>）都重命名為 <code>b1.txt</code>、<code>b2.txt</code>、<code>b3.txt</code>。</p><p><strong>解釋</strong></p><p>在上面的例子中，第一個參數（<code>a\\*</code>）是 “from” 模式，第二個參數是 “to” 模式（<code>b\\#1</code>）。根據上面的例子，<code>mmv</code> 將查找任何以字母 “a” 開頭的文件名，並根據第二個參數重命名匹配的文件，即 “to” 模式。我們可以使用通配符，例如用 <code>*</code>、<code>?</code> 和 <code>[]</code> 來匹配一個或多個任意字符。請注意，你必須轉義使用通配符，否則它們將被 shell 擴展，<code>mmv</code> 將無法理解。</p><p>“to” 模式中的 <code>#1</code> 是通配符索引。它匹配 “from” 模式中的第一個通配符。 “to” 模式中的 <code>#2</code> 將匹配第二個通配符（如果有的話），依此類推。在我們的例子中，我們只有一個通配符（星號），所以我們寫了一個 <code>#1</code>。並且，<code>#</code> 符號也應該被轉義。此外，你也可以用引號括起模式。</p><p>你甚至可以將具有特定擴展名的所有文件重命名為其他擴展名。例如，要將當前目錄中的所有 <code>.txt</code> 文件重命名為 <code>.doc</code> 文件格式，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mmv \\*.txt \\#1.doc</span></span></code></pre></div><p>這是另一個例子。 我們假設你有以下文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>abcd1.txt abcd2.txt abcd3.txt</span></span></code></pre></div><p>你希望在當前目錄下的所有文件中將第一次出現的 “abc” 替換為 “xyz”。 你會怎麼做呢？</p><p>很簡單。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mmv &#39;*abc*&#39; &#39;#1xyz#2&#39;</span></span></code></pre></div><p>請注意，在上面的示例中，模式被單引號括起來了。</p><p>讓我們檢查下 “abc” 是否實際上被替換為 “xyz”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>xyzd1.txt xyzd2.txt xyzd3.txt</span></span></code></pre></div><p>看到沒？ 文件 <code>abcd1.txt</code>、<code>abcd2.txt</code> 和 <code>abcd3.txt</code> 已經重命名為 <code>xyzd1.txt</code>、<code>xyzd2.txt</code> 和 <code>xyzd3.txt</code>。</p><p><code>mmv</code> 命令的另一個值得注意的功能是你可以使用 <code>-n</code> 選項打印輸出而不是重命名文件，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mmv -n a\\* b\\#1</span></span>
<span class="line"><span>a1.txt -&gt; b1.txt</span></span>
<span class="line"><span>a2.txt -&gt; b2.txt</span></span>
<span class="line"><span>a3.txt -&gt; b3.txt</span></span></code></pre></div><p>這樣，你可以在重命名文件之前簡單地驗證 <code>mmv</code> 命令實際執行的操作。</p><p>有關更多詳細信息，請參閲 man 頁面。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man mmv</span></span></code></pre></div><h3 id="更新-thunar-文件管理器" tabindex="-1">更新：Thunar 文件管理器 <a class="header-anchor" href="#更新-thunar-文件管理器" aria-label="Permalink to “更新：Thunar 文件管理器”">​</a></h3><p><strong>Thunar 文件管理器</strong>默認具有內置<strong>批量重命名</strong>選項。 如果你正在使用 Thunar，那麼重命名文件要比使用 <code>mmv</code> 命令容易得多。</p><p>Thunar 在大多數 Linux 發行版的默認倉庫庫中都可用。</p><p>要在基於 Arch 的系統上安裝它，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S thunar</span></span></code></pre></div><p>在 RHEL、CentOS 上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install thunar</span></span></code></pre></div><p>在 Fedora 上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install thunar</span></span></code></pre></div><p>在 openSUSE 上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper install thunar</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install thunar</span></span></code></pre></div><p>安裝後，你可以從菜單或應用程序啓動器中啓動批量重命名程序。 要從終端啓動它，請使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ thunar -B</span></span></code></pre></div><p>批量重命名方式如下。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/06/bulk-rename.png" alt=""></p><p>單擊“+”，然後選擇要重命名的文件列表。 批量重命名可以重命名文件的名稱、文件的後綴或者同時重命名文件的名稱和後綴。 Thunar 目前支持以下批量重命名：</p><ul><li>插入日期或時間</li><li>插入或覆蓋</li><li>編號</li><li>刪除字符</li><li>搜索和替換</li><li>大寫或小寫</li></ul><p>當你從選項列表中選擇其中一個條件時，你將在“新名稱”列中看到更改的預覽，如下面的屏幕截圖所示。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/06/bulk-rename-1.png" alt=""></p><p>選擇條件後，單擊“重命名文件”選項來重命名文件。</p><p>你還可以通過選擇兩個或更多文件從 Thunar 中打開批量重命名器。 選擇文件後，按 F2 或右鍵單擊並選擇“重命名”。</p><p>嗯，這就是本次的所有內容了。希望有所幫助。更多幹貨即將到來。敬請關注！</p><p>祝快樂！</p><hr>`,59)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),e(t,{href:"https://www.ostechnix.com/how-to-rename-multiple-files-at-once-in-linux/"},{default:a(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-rename-multiple-files-at-once-in-linux/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=i("作者：",-1)),e(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),e(t,{href:"https://github.com/Flowsnow"},{default:a(()=>[...s[4]||(s[4]=[i("Flowsnow",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:a(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const v=l(c,[["render",r]]);export{y as __pageData,v as default};
